(() => {
  const data = JSON.parse(document.getElementById('data').textContent);
  const grid = document.querySelector('.lounge-gallery-grid');
  const copy = document.getElementById('copy');
  const fallback = document.getElementById('fallback');
  const picks = document.getElementById('picks');
  const storageKey = 'lounge:picks:' + data.exportedAt;
  const liked = new Set();
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) || '[]');
    if (Array.isArray(saved)) {
      for (const sku of saved) if (data.items.some(item => item.sku === sku)) liked.add(sku);
    }
  } catch { /* Storage can be blocked for local files. */ }
  const money = price => (price / 100).toFixed(2) + ' zł';
  const element = (tag, className, text) => {
    const node = document.createElement(tag);
    node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  };

  function render() {
    const items = [...data.items].sort((a, b) => {
      const price = a.price - b.price;
      const discount = b.discount - a.discount;
      return (data.sort === 'cheapest' ? price || discount : discount || price) ||
        (a.sku < b.sku ? -1 : a.sku > b.sku ? 1 : 0);
    });
    grid.replaceChildren(...items.map(item => {
      const name = (item.brand + ' ' + item.name).trim();
      const card = element('article', 'lounge-share-card');
      card.dataset.sku = item.sku;
      const link = element('a', 'lounge-gallery-card');
      link.href = item.url;
      link.target = '_blank';
      link.rel = 'noreferrer';
      link.setAttribute('aria-label', name + ', ' + money(item.price));
      const photo = element('div', 'lounge-gallery-photo');
      if (item.photo) {
        const img = element('img', 'gallery-image');
        img.src = item.photo;
        img.alt = name;
        photo.append(img);
      } else {
        const placeholder = element('span', 'lounge-gallery-placeholder', item.brand.trim().charAt(0).toUpperCase() || '—');
        placeholder.setAttribute('role', 'img');
        placeholder.setAttribute('aria-label', name);
        photo.append(placeholder);
      }
      if (item.discount > 0) photo.append(element('span', 'lounge-gallery-discount', '−' + item.discount + '%'));
      const details = element('div', 'lounge-gallery-details');
      const title = element('span', 'lounge-gallery-name', item.name);
      title.title = item.name;
      const prices = element('span', 'lounge-gallery-prices');
      prices.append(element('strong', '', money(item.price)));
      if (item.originalPrice > item.price) prices.append(element('s', 'muted', money(item.originalPrice)));
      details.append(element('strong', '', item.brand), title, prices, element('span', 'muted', item.colour));
      if (item.material) details.append(element('span', 'muted lounge-gallery-material', item.material));
      if (item.specs) details.append(element('span', 'muted lounge-gallery-material', item.specs));
      for (const status of item.statuses) {
        const badge = element('span', 'lounge-status', status.label);
        badge.dataset.cart = status.cart;
        badge.dataset.tone = status.tone;
        details.append(badge);
      }
      link.append(photo, details);
      const like = element('button', 'like');
      like.type = 'button';
      like.setAttribute('aria-label', 'Like ' + name);
      like.setAttribute('aria-pressed', String(liked.has(item.sku)));
      like.textContent = liked.has(item.sku) ? '♥' : '♡';
      like.addEventListener('click', () => {
        if (liked.has(item.sku)) liked.delete(item.sku); else liked.add(item.sku);
        try { localStorage.setItem(storageKey, JSON.stringify([...liked])); } catch { /* Optional. */ }
        like.setAttribute('aria-pressed', String(liked.has(item.sku)));
        like.textContent = liked.has(item.sku) ? '♥' : '♡';
        updateCopy();
      });
      card.append(link, like);
      return card;
    }));
    document.querySelectorAll('[data-sort]').forEach(button => {
      button.setAttribute('aria-pressed', String(button.dataset.sort === data.sort));
    });
  }
  function updateCopy() {
    copy.textContent = 'Copy picks (' + liked.size + ')';
    copy.disabled = liked.size === 0;
    fallback.hidden = true;
  }
  document.querySelectorAll('[data-sort]').forEach(button => {
    button.addEventListener('click', () => { data.sort = button.dataset.sort; render(); });
  });
  copy.addEventListener('click', async () => {
    const text = data.items.filter(item => liked.has(item.sku))
      .map(item => (item.brand + ' ' + item.name).replace(/[\r\n]+/g, ' ').trim() + ' · ' + money(item.price) + ' · ' + item.url)
      .join('\n');
    try {
      await navigator.clipboard.writeText(text);
      fallback.hidden = true;
    } catch {
      picks.value = text;
      fallback.hidden = false;
      picks.focus();
      picks.select();
    }
  });
  render();
  updateCopy();
})();
